blocks.source:
func invoice(prices []int64, quantities []int64, discount int64, rate int64) int64 {
    if (int64(len(prices)) != int64(len(quantities))) {
        return (-1)
    }
    var subtotal int64 = 0
    for i := int64(0); i < int64(len(prices)); i++ {
        if ((prices[i] < 0) || (quantities[i] <= 0)) {
            return (-2)
        }
        subtotal += (prices[i] * quantities[i])
    }
    var net int64 = (subtotal - ((subtotal * discount) / 10000))
    return (net + fee_component(net, rate))
}

func fee_component(amount int64, rate int64) int64 {
    if (amount <= 0) {
        return 0
    }
    return ((amount * rate) / 10000)
}

func tax_inclusive(gross int64, rate int64, exempt bool) int64 {
    if (gross < 0) {
        return (-1)
    }
    if exempt {
        return 0
    }
    if (rate < 0) {
        return (-2)
    }
    var denominator int64 = (10000 + rate)
    var numerator int64 = (gross * rate)
    var rounding int64 = (denominator / 2)
    var tax int64 = ((numerator + rounding) / denominator)
    if (tax > gross) {
        return (-3)
    }
    return tax
}

func order_total(prices []int64, quantities []int64, discount int64) int64 {
    if (int64(len(prices)) != int64(len(quantities))) {
        return (-1)
    }
    if ((discount < 0) || (discount > 10000)) {
        return (-2)
    }
    var subtotal int64 = 0
    for i := int64(0); i < int64(len(prices)); i++ {
        if (prices[i] < 0) {
            return (-3)
        }
        if (quantities[i] <= 0) {
            return (-4)
        }
        subtotal += (prices[i] * quantities[i])
    }
    var reduction int64 = ((subtotal * discount) / 10000)
    return (subtotal - reduction)
}

