class Pipeline {
    static long capture_payment(long authorized, long requested, long captured, boolean expired) {
        if (expired) {
            return (-1);
        }
        if ((requested <= 0)) {
            return (-2);
        }
        long remaining = (authorized - captured);
        if ((remaining <= 0)) {
            return (-3);
        }
        if ((requested > remaining)) {
            return (-4);
        }
        long total = (captured + requested);
        if ((total == authorized)) {
            return 2;
        }
        if ((total < authorized)) {
            return 1;
        }
        return (-5);
    }

static long retry_delay(long attempt, long initial, long cap, long jitter) {
    if (((attempt < 0) || (initial <= 0))) {
        return (-1);
    }
    long delay = initial;
    long count = 0;
    while ((count < attempt)) {
        if ((delay >= (cap / 2))) {
            delay = cap;
            break;
        }
        delay *= 2;
        count += 1;
    }
    long bounded = Math.min(delay, cap);
    if ((jitter < 0)) {
        jitter = 0;
    }
    return Math.min((bounded + jitter), cap);
}

class Pipeline {
    static long capture(long authorized, long requested, long captured, boolean expired) {
        if (expired) {
            return (-1);
        }
        if ((requested <= 0)) {
            return (-2);
        }
        long remaining = (authorized - captured);
        if ((remaining <= 0)) {
            return (-3);
        }
        if ((requested > remaining)) {
            return (-4);
        }
        long total = (captured + requested);
        if ((total == authorized)) {
            return 2;
        }
        if ((total < authorized)) {
            return 1;
        }
        return (-5);
    }

static long refund(long captured, long refunded, long requested, boolean disputed) {
    if (disputed) {
        return (-1);
    }
    if ((refunded < 0)) {
        return (-2);
    }
    if ((requested <= 0)) {
        return (-3);
    }
    long available = (captured - refunded);
    if ((requested > available)) {
        return (-4);
    }
    long total = (refunded + requested);
    if ((total == captured)) {
        return 2;
    }
    return 1;
}

static long retry_delay(long attempt, long initial, long cap, long jitter) {
    if (((attempt < 0) || (initial <= 0))) {
        return (-1);
    }
    long delay = initial;
    long count = 0;
    while ((count < attempt)) {
        if ((delay >= (cap / 2))) {
            delay = cap;
            break;
        }
        delay *= 2;
        count += 1;
    }
    long bounded = Math.min(delay, cap);
    if ((jitter < 0)) {
        jitter = 0;
    }
    return Math.min((bounded + jitter), cap);
}

static long cache_lifetime(long now, long created, long accessed, long ttl, long idle) {
    if (((created > now) || (accessed > now))) {
        return (-1);
    }
    long absolute = (created + ttl);
    long sliding = (accessed + idle);
    long deadline = Math.min(absolute, sliding);
    if ((deadline <= now)) {
        return 0;
    }
    long remaining = (deadline - now);
    if ((remaining > ttl)) {
        return ttl;
    }
    return remaining;
}

