blocks.source:
def capture_payment(authorized: int, requested: int, captured: int, expired: bool) -> int:
    if expired:
        return -1
    if requested <= 0:
        return -2
    remaining = authorized - captured
    if remaining <= 0:
        return -3
    if requested > remaining:
        return -4
    total = captured + requested
    if total == authorized:
        return 2
    if total < authorized:
        return 1
    return -5

def retry_delay(attempt: int, initial: int, cap: int, jitter: int) -> int:
    if attempt < 0 or initial <= 0:
        return -1
    delay = initial
    count = 0
    while count < attempt:
        if delay >= cap // 2:
            delay = cap
            break
        delay *= 2
        count += 1
    bounded = min(delay, cap)
    if jitter < 0:
        jitter = 0
    return min(bounded + jitter, cap)

def capture(authorized: int, requested: int, captured: int, expired: bool) -> int:
    if expired:
        return -1
    if requested <= 0:
        return -2
    remaining = authorized - captured
    if remaining <= 0:
        return -3
    if requested > remaining:
        return -4
    total = captured + requested
    if total == authorized:
        return 2
    if total < authorized:
        return 1
